// Native vector reconstruction of the Level 4 preview's mechanical crest.
export function chaosBadgeMarkup(){return `<svg class="chaos-crest" viewBox="0 0 180 180" aria-label="混沌序曲击杀徽章"><g class="crest-halo" fill="none" stroke="#efe8db"><circle cx="90" cy="89" r="66" stroke-width="1"/><circle cx="90" cy="89" r="47" stroke-width="2"/><path d="M6 90h28m112 0h28M10 96h24m112 0h24" opacity=".7"/></g><g class="crest-crown" fill="none" stroke="#f0dedb" stroke-width="1.5"><path d="M74 24l8-6V9l8-7 8 7v9l8 6M81 26l5-9V9l4-3 4 3v8l5 9"/><path d="M75 29l5 5 5-2 5 4 5-4 5 2 5-5" stroke="#fb244f" stroke-width="5"/></g><g class="crest-body" stroke="#343337" stroke-width="2.5" stroke-linejoin="round"><path fill="#bbb8b4" d="M84 43L65 50 56 65v35l10 15 9 4 5 22 10 6 10-6 5-22 9-4 10-15V65l-9-15-19-7-1 17H85z"/><path fill="#eee7d9" d="M78 49l-11 9-4 10v25l12 6 3 12-11-7V70l11-10zm24 0 11 9 4 10v25l-12 6-3 12 11-7V70l-11-10z"/><path fill="#7b7d7d" d="M85 42h10v23H85zm-3 62h5v37l-6-6-3-28zm11 0h5l4 3-3 28-6 6z"/><path fill="#171a1e" d="M80 65h20l8 15-8 19H80L72 80z"/><path fill="#de1541" stroke="#ff6070" stroke-width="1" d="M79 72h22L90 89z"/><path fill="none" stroke="#f3818c" stroke-width=".7" d="M79 72l11 6 11-6m-11 6v11"/></g><g class="crest-sparks" fill="#ff254b"><path d="M31 53l13-18-6 15 8 2-15 10zM139 119l-9 18 5-15-9-2 16-10zM48 118l-10-2 8 8zM126 48l9 6-2-12z"/></g></svg>`;}
export function updateChaosBadge(element,seconds){if(!element)return;const t=Math.max(0,seconds),body=element.querySelector('.crest-body'),halo=element.querySelector('.crest-halo'),spark=element.querySelector('.crest-sparks'),crown=element.querySelector('.crest-crown');if(!body)return;const pop=t<.1?.45+t*6.8:t<.22?1.13-(t-.1)*1.08:1;body.style.transform=`translate(90px,90px) scale(${pop}) translate(-90px,-90px)`;halo.style.opacity=Math.min(1,Math.max(0,(t-.08)*8));halo.style.transform=`translate(90px,89px) rotate(${Math.max(0,1-t/.55)*45}deg) scale(${1+Math.max(0,.22-t)}) translate(-90px,-89px)`;spark.style.opacity=t>.12&&t<.62?Math.sin((t-.12)*Math.PI/.5):0;crown.style.opacity=Math.min(1,t*4);element.style.opacity=t<1.8?1:Math.max(0,1-(t-1.8)/.4);}
export class ChaosAudio{
 constructor(){this.buffers=new Map();this.loading=null;this.active=new Map();}
 async preload(ctx){if(!ctx||this.loading)return this.loading;this.loading=Promise.allSettled(['equip','shot','kill'].filter(key=>!this.buffers.has(key)).map(async key=>{const r=await fetch(new URL(`./assets/chaos/${key}.mp3`,import.meta.url));if(!r.ok)throw Error(key);const b=await ctx.decodeAudioData(await r.arrayBuffer());this.buffers.set(key,b);})).finally(()=>{this.loading=null});return this.loading;}
 play(ctx,key,volume=1){if(!ctx||!volume)return false;const buffer=this.buffers.get(key.startsWith('kill')?'kill':key);if(!buffer)return false;const group=key.startsWith('kill')?'kill':key;if(group!=='shot')this.stop(group);const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=volume;source.connect(gain);gain.connect(ctx.destination);source.start();this.active.set(group,source);source.onended=()=>{source.disconnect();gain.disconnect();if(this.active.get(group)===source)this.active.delete(group)};return true;}
 stop(group){try{this.active.get(group)?.stop()}catch{}this.active.delete(group);}
}
